// 2026 TableX Base Series — authoritative marketing catalog.
//
// Source: "2026 Base Series Descriptions.docx" (Brian Craig, Apr 2026). Copy
// was generated by Brian against the Everyman / Outlaw archetype baseline.
//
// The legacy two-digit SKU codes in sku-registry.ts and product-catalog.json
// are PLACEHOLDER names from the initial seed phase (e.g. "Studio", "Nexus",
// "Alliance"). Use this catalog as the authoritative source of series identity;
// the `code` field maps to the legacy numeric code where known.
//
// Per Brian's Apr 15 email: Fundamental (code 33) will be rolled into
// Foundation as a no-cost option (plastic foot cap) rather than stand alone.

export type SeriesCode = string;

export interface SeriesEntry {
  /** Uppercase canonical name (e.g. "ULTRA", "FOUNDATION"). */
  slug: string;

  /** Display name (e.g. "Ultra", "VertiGO"). */
  name: string;

  /** Legacy two-digit code from sku-registry.ts, or null if unmapped. */
  code: SeriesCode | null;

  /** Short headline pulled from the marketing description. */
  headline: string;

  /** Full marketing paragraph. */
  description: string;

  /** Primary design traits / capabilities. */
  tags: string[];

  /** Photography / filter "Workspaces" from the Apr 2026 shot list. */
  workspaces: Workspace[];

  /** Photography / filter "Applications" from the Apr 2026 shot list. */
  applications: Application[];
}

export type Workspace =
  | "Workplace"
  | "Education"
  | "Hospitality"
  | "Healthcare"
  | "Outdoor";

export type Application =
  | "Training & Classroom"
  | "Café & Dining"
  | "Collaborative & Meeting"
  | "Occasional"
  | "Height-Adjustable"
  | "Nesting & Folding"
  | "Pull Up"
  | "Conference";

