export const seriesBySlug = new Map(seriesCatalog.map((s) => [s.slug, s]));
export const seriesByCode = new Map(
  seriesCatalog.filter((s) => s.code !== null).map((s) => [s.code!, s]),
);

export function getSeriesBySlug(slug: string): SeriesEntry | undefined {
  return seriesBySlug.get(slug.toUpperCase());
}

export function getSeriesByCode(code: string): SeriesEntry | undefined {
  return seriesByCode.get(code);
}

/** Series whose legacy numeric code is still unmapped — needs Brian's input. */
export const unmappedSeries: SeriesEntry[] = seriesCatalog.filter((s) => s.code === null);
